    const attachments=byId('attachments');if(attachments){const block=history.querySelector('.order-section-body');const body=attachments.querySelector('.order-section-body');if(body){while(body.firstChild)block.append(body.firstChild);}attachments.remove();}
    const refreshed=[...form.querySelectorAll(':scope > .order-section')],current=id=>refreshed.find(x=>x.dataset.orderSection===id);const order=['basic','products','pi','amounts','remarks','ci','history'];for(const id of order){const section=current(id);if(section)form.insertBefore(section,form.querySelector('.pi-signing-status')||form.querySelector('.order-sticky-actions'));}
