      const source=missing.querySelector('span'),links=source?[...source.querySelectorAll('.missing-link')]:[];
      const toggle=document.createElement('button');toggle.type='button';toggle.className='missing-summary-toggle';toggle.dataset.toggleMissing='';toggle.setAttribute('aria-expanded','false');toggle.textContent=links.length?`Final PI 尚有 ${links.length} 项待补充`:'Draft主要资料已完整';
      const details=document.createElement('div');details.className='missing-details';details.hidden=true;
