      const group=(className,label,items)=>{const el=document.createElement('div');el.className=`action-group ${className}`;const text=document.createElement('span');text.className='action-label';text.textContent=label;el.append(text,...items);return el;};
      const find=selector=>buttons.find(button=>button.matches(selector));
      const save=find('button[type="submit"]'),draft=find('[data-preview-draft-pi]'),electronic=find('[data-final-pi-mode="Electronic"]'),unsigned=find('[data-generate-final-pi]'),print=find('[data-final-pi-mode="Print"]'),ci=find('[data-generate-ci]');
