    if(errors.length){const toggle=document.createElement('button');toggle.type='button';toggle.className='ci-missing-toggle';toggle.textContent=`展开 Final CI 缺失项（${errors.length}）`;const list=document.createElement('div');list.className='ci-missing-list';list.hidden=true;const names=[['Actual Shipment Date','actualShipmentDate'],['Actual Transport Method','actualTransportMethod'],['actual transport','actualTransportMethod'],['Port of Loading','portOfLoading'],['Port of Discharge','portOfDischarge'],['Shipment Date','actualShipmentDate'],['Declaration','declaration']];errors.forEach(error=>{const row=document.createElement('button');row.type='button';row.className='missing-link';row.textContent=error;const found=names.find(([key])=>error.toLowerCase().includes(key.toLowerCase()));if(found){row.dataset.missingSection='ci';row.dataset.missingName=found[1];}list.append(row);});toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!open));list.hidden=open;});toggle.setAttribute('aria-expanded','false');statusBox.append(toggle,list);}
    body.prepend(statusBox);
    const customer=state.customers.find(x=>x.id===o.customerId)||{},parties=document.createElement('section');parties.className='ci-parties ci-subsection';parties.innerHTML=`<div class="ci-subsection-heading"><strong>Document Parties</strong><span>关联信息 / 只读</span></div><div class="ci-parties-grid"><div><span>Buyer</span><b>${esc(customer.companyName||customer.buyerName||'未选择')}</b></div><div><span>Consignee</span><b>${esc(customer.consigneeName||'-')}</b></div><div><span>Related PI</span><b>${esc(o.ciDocument?.relatedPiNumber||o.piNumber||'-')}</b></div><div><span>CI Number</span><b>${esc(o.ciNumber||'-')}</b></div><div><span>Order Number</span><b>${esc(o.orderNumber||'-')}</b></div>${o.shipmentReference?`<div><span>Shipment Reference</span><b>${esc(o.shipmentReference)}</b></div>`:''}</div>`;body.insertBefore(parties,statusBox.nextSibling);
    const grid=body.querySelector(':scope > .form-grid');
    if(grid&&!grid.dataset.ciGrouped){grid.dataset.ciGrouped='true';const groups=document.createElement('div');groups.className='ci-field-groups';const make=(className,title,subtitle,names)=>{const section=document.createElement('section');section.className=`ci-group ${className}`;section.innerHTML=`<div class="ci-subsection-heading"><strong>${title}</strong><span>${subtitle}</span></div>`;names.forEach(name=>{const field=grid.querySelector(`[name="${name}"]`)?.closest('.field');if(field)section.append(field);});return section;};const shipment=make('ci-shipment','Actual Shipment','实际出货确认',['actualShipmentDate','actualTransportMethod','actualTransportMethodOther','actualTransportConfirmed','carrier']);const reference=make('ci-reference','Transport Reference','运输单据',['transportDocumentType','transportDocumentTypeOther','transportDocumentNumber','vesselFlightNumber']);const route=make('ci-route','Route & Arrival','路线与到达',['portOfLoading','portOfDischarge','estimatedArrivalDate','purposeOfShipment','purposeOfShipmentOther']);const declaration=make('ci-declaration','Declaration','正式单据内容',['declaration','showPaymentStatusOnCI']);const note=grid.parentElement.querySelector(':scope > .section-note'),related=grid.parentElement.querySelector(':scope > .related-document');if(note)shipment.prepend(note);if(related)shipment.prepend(related);groups.append(shipment,reference,route,declaration);grid.replaceWith(groups);}
