    ['subtotal','total','depositAmount','balancePayment','amountPaid','outstandingAmount','amountPayableNow'].forEach(k=>{const el=$(`[name="${k}"]`);if(el)el.value=C.money(o[k]).toFixed(2)});
    ['total','depositAmount','amountPaid','outstandingAmount','amountPayableNow'].forEach(k=>{const el=$(`[data-order-summary="${k}"]`);if(el)el.textContent=C.money(o[k]).toFixed(2)});
    ['total','amountPaid','outstandingAmount','amountPayableNow'].forEach(k=>{const el=$(`[data-ci-summary="${k}"]`);if(el)el.textContent=C.money(o[k]).toFixed(2)});const ciCurrency=$('[data-ci-summary="currency"]');if(ciCurrency)ciCurrency.textContent=o.currency||'';
    o.items.forEach((i,n)=>{const card=$(`[data-line="${n}"]`);if(!card)return;const amount=$('[name="amount"]',card),cbm=$('[name="cbm"]',card),warning=$('[data-item-warning]',card);if(amount)amount.value=C.money(i.amount).toFixed(2);if(cbm)cbm.value=C.asNumber(i.cbm).toFixed(3);if(warning){const mismatch=i.cartonQty>0&&i.quantityPerCarton>0&&Math.abs(i.cartonQty*i.quantityPerCarton-i.quantity)>.0001;warning.textContent=mismatch?'Carton Quantity × Quantity per Carton does not match Quantity.':'';warning.classList.toggle('visible',mismatch);}});
