    const tradeWarning=$('#trade-warning');if(tradeWarning)tradeWarning.innerHTML=C.tradeWarnings(o).map(x=>`<div class="warning">${esc(x)}</div>`).join('');
    const revisionButton=$('[data-create-pi-revision]');if(revisionButton)revisionButton.disabled=!C.latestPISnapshot(o)||!C.needsPIRevision(o);
