  function partyBlock(title,lines){return `<div class="paper-box"><strong>${title}</strong><br>${lines.filter(Boolean).map(esc).join('<br>')}</div>`;}
  function companyParty(company=state.company){const c=company;return [C.companyEnglishName(c),c.address,c.telephone?`Tel: ${c.telephone}`:'',c.email,c.website];}
  function buyerParty(customer){const address=String(customer.address||''),country=String(customer.country||''),countryLine=country&&!address.toLocaleLowerCase().includes(country.toLocaleLowerCase())?country:'';return [customer.companyName||customer.buyerName,customer.buyerType==='Individual'?customer.buyerName:'',address,countryLine,customer.contactPerson?`Attn: ${customer.contactPerson}`:'',customer.telephone,customer.email];}
