    const hasRevision=o.relatedPiRevision!==''&&o.relatedPiRevision!=null,relatedPi=hasRevision?`${o.relatedPiNumber||o.piNumber} / Revision ${o.relatedPiRevision}`:(o.relatedPiNumber||o.piNumber),meta=type==='PI'?[['PI Number',o.piDisplayNumber||o.piNumber],['Revision',o.piRevision??0],['Order Number',o.orderNumber],['Date',o.createdDate],['Valid Until',o.validUntil],['Currency',o.currency],['Trade Term',C.formatTradeTerm(o)],['Payment Term',o.paymentTerm],['Delivery Time',o.deliveryTime],['Planned Transport Method',plannedMethod]]:type==='CI'?[['Invoice Number',o.ciNumber],...(o.standalone?[]:[['Related PI',relatedPi],['Order Number',o.orderNumber]]),['Invoice Date',o.createdDate],['Country of Origin',o.countryOfOrigin],['Currency',o.currency],['Trade Term',C.formatTradeTerm(o)],['Purpose',purpose],...shipmentMeta]:[['Packing List No.',o.packingListNumber],['Related CI',o.relatedCiNumber||o.ciNumber],['Related PI',relatedPi],['Order Number',o.orderNumber],['Trade Term',C.formatTradeTerm(o)],...shipmentMeta.filter(([label])=>!['Vessel / Flight Number','Estimated Arrival Date'].includes(label))];
    const metaHtml=`<table><tbody>${meta.map((x,i)=>i%2===0?`<tr><th>${esc(x[0])}</th><td>${esc(x[1])}</td>${meta[i+1]?`<th>${esc(meta[i+1][0])}</th><td>${esc(meta[i+1][1])}</td>`:'<th></th><td></td>'}</tr>`:'').join('')}</tbody></table>`;
    let table='';
    if(type==='PL')table=`<table><thead><tr><th>Item</th><th>Product Description</th><th>Model / SKU</th><th>Carton No.</th><th>Qty / Carton</th><th>Total Qty</th><th>N.W.</th><th>G.W.</th><th>Dimensions</th><th>Cartons</th><th>CBM</th></tr></thead><tbody>${o.items.map((i,n)=>`<tr><td>${n+1}</td><td>${esc(i.description)}</td><td>${esc(C.formatModelSku(i.modelSku))}</td><td>${n+1}</td><td>${i.quantityPerCarton||i.quantity}</td><td>${i.packingQuantity||i.quantity}</td><td>${i.netWeight.toFixed(2)} KG</td><td>${i.grossWeight.toFixed(2)} KG</td><td>${i.cartonLength} × ${i.cartonWidth} × ${i.cartonHeight} cm</td><td>${i.cartonQty}</td><td>${i.cbm.toFixed(3)}</td></tr>`).join('')}</tbody></table><div class="paper-summary"><div><span>TOTAL CARTONS</span><b>${o.totalCartons}</b></div><div><span>TOTAL NET WEIGHT</span><b>${o.totalNetWeight.toFixed(2)} KG</b></div><div><span>TOTAL GROSS WEIGHT</span><b>${o.totalGrossWeight.toFixed(2)} KG</b></div><div><span>TOTAL CBM</span><b>${o.totalCBM.toFixed(3)}</b></div></div>`;
    else table=`<table><thead><tr><th>Item</th><th>Product Description</th><th>Model / SKU</th><th>Material</th><th>HS Code</th><th>Quantity</th><th>Unit</th><th class="amount">Unit Price</th><th class="amount">Amount</th></tr></thead><tbody>${o.items.map((i,n)=>{const qty=type==='CI'?(i.ciQuantity??i.quantity):i.quantity;return `<tr><td>${n+1}</td><td>${esc(i.description)}</td><td>${esc(C.formatModelSku(i.modelSku))}</td><td>${esc(i.material)}</td><td>${esc(i.hsCode)}</td><td>${qty}</td><td>${esc(i.unit)}</td><td class="amount">${C.formatMoney(i.unitPrice,o.currency)}</td><td class="amount">${C.formatMoney(qty*i.unitPrice,o.currency)}</td></tr>`}).join('')}</tbody></table>${amountSummary(o,type)}`;
