    const electronic=settings.signingMode==='Electronic';
    const sign=settings.version==='Final'&&settings.includeSigningBlock?`<div class="paper-sign ${electronic?'electronic':'print-sign'}"><div class="paper-sign-head"><strong>FOR AND ON BEHALF OF THE SELLER</strong><span>${esc(companyName)}</span></div><div class="paper-signature"><strong>AUTHORIZED SIGNATURE</strong><div class="signature-image">${electronic&&co.signature?`<img src="${co.signature}" alt="Signature">`:''}</div>${electronic?'':'<div class="signature-line"></div>'}<span>Name: ${esc(co.authorizedSignatoryName||'')}</span><span>Title: ${esc(co.authorizedSignatoryTitle||'')}</span><span>Date: ${esc(settings.signedDate)}</span></div><div class="paper-stamp"><strong>COMPANY STAMP</strong><div class="stamp-box">${electronic&&co.stamp?`<img src="${co.stamp}" alt="Company Stamp">`:''}</div></div></div>`:'';
